#define R(a)  mat2(cos(a + 1.57*vec4(0,-1,1,0)))  //rotation matrix using pi/2 phase offset for sin
#define N     normalize

float t;
vec2 mm;

vec3 f(vec3 p) {
    vec3  o = vec3(3,-1,1), q;
    float d=100.,i=0.;

    for( p.xz *= R(t/10.) ; i++<41. ; )

        p.xy *= R(mm.x), p.xz *= R(mm.y),
        p = ( cos(p)*p ),

#define S(p) p.x < p.y ? p = p.yx : p     
        S(p.xy),S(p.xz), S(p.yz),

        p -= o*.001; 
        q = p ;

        vec2 h = vec2(.1,2.);
        d = min(d, max(p.z-h.y,max(p.x*.866+p.y*.5,-p.y)-h.x*.5) ); 

        d*=d;

    return q / d ;
}

void mainImage(out vec4 O, vec2 U) {
    t = iTime*3.;
    vec3 R = iResolution,
         D = N( vec3( (2.*U-R.xy), .5*R.y) ),
         P = R-R; P.z = -.04 - .02*sin(iTime/5.) ;

    mm = vec2(2);

    O = vec4(0);

    for ( float i=0.; i<10.; i++) { 
        vec3 vc = f(P);
        vc = log( 2.5 - exp(-vc*vc) );
        O.xyz += (vc.x*vec3(1,0,.5) + vc.y*vec3(.6,.5,0) + vc.z*vec3(0,.5,1))*exp(-i*i*1e-2) ;

        P += D*.003;
    }

    O = cos(O);
    O *= O;
    O *= O;


}
